// new_mobile_app.txt
// Initial mobile app prototype — a simple contact list with add, remove, and search functionality.
// Tech stack: React, React Native (example), and a mock data source.

import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList, TouchableOpacity, Modal, StyleSheet } from 'react-native';

const MOCK_CONTACTS = [
  { id: 1, name: 'Alice Johnson', email: 'alice@example.com', phone: '555-1234' },
  { id: 2, name: 'Bob Smith', email: 'bob@example.com', phone: '555-5678' },
  { id: 3, name: 'Charlie Brown', email: 'charlie@example.com', phone: '555-9012' },
];

export default function ContactList() {
  const [contacts, setContacts] = useState(MOCK_CONTACTS);
  const [input, setInput] = useState('');
  const [search, setSearch] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedContact, setSelectedContact] = useState(null);
  const [filter, setFilter] = useState('All');

  const filteredContacts = contacts.filter(contact =>
    contact.name.toLowerCase().includes(search.toLowerCase()) &&
    filter === 'All' || filter === contact.email.toLowerCase() || filter === contact.phone.toLowerCase()
  );

  const addContact = () => {
    if (!input.trim()) return;
    const newContact = {
      id: Date.now(),
      name: input,
      email: input.split('@')[0] || 'nouser@example.com',
      phone: input.split('@')[1] || '',
    };
    setContacts([...contacts, newContact]);
    setInput('');
    setShowAddModal(false);
  };

  const removeContact = (id) => {
    setContacts(contacts.filter(c => c.id !== id));
    setSelectedContact(null);
  };

  const selectContact = (contact) => {
    setSelectedContact(contact);
    setShowAddModal(true);
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>My Contact List</Text>
      <Text style={styles.subtitle}>Add and search contacts quickly.</Text>

      <TextInput
        style={styles.input}
        placeholder="Enter name, email, or phone..."
        value={input}
        onChangeText={setInput}
      />

      <TextInput
        style={styles.searchInput}
        placeholder="Search..."
        value={search}
        onChangeText={setSearch}
        placeholderTextColor="#999"
      />

      <Button title="+ Add Contact" onPress={() => setShowAddModal(true)} />

      <Button title="Filter" onPress={() => setFilter(filter)} />

      {filteredContacts.length > 0 && (
        <FlatList
          data={filteredContacts}
          keyExtractor={(item) => item.id.toString()}
          renderItem={({ item }) => (
            <TouchableOpacity
              style={styles.contactItem}
              onPress={() => selectContact(item)}
            >
              <Text style={styles.contactName}>{item.name}</Text>
              <Text style={styles.contactInfo}>{item.email}</Text>
              <Text style={styles.contactInfo}>{item.phone}</Text>
              <TouchableOpacity onPress={() => removeContact(item.id)}>
                <Text style={styles.deleteIcon}>✕</Text>
              </TouchableOpacity>
            </TouchableOpacity>
          )}
        />
      )}

      <Modal
        visible={showAddModal}
        animationType="slide"
        presentationStyle="fullScreen"
        onRequestClose={() => setShowAddModal(false)}
      >
        <View style={styles.modal}>
          <Text style={styles.modalTitle}>Add a New Contact</Text>
          <TextInput
            style={styles.contactInput}
            placeholder="Name"
            value={input}
            onChangeText={setInput}
          />
          <TextInput
            style={styles.contactInput}
            placeholder="Email (optional)"
            value={input}
            onChangeText={setInput}
          />
          <TextInput
            style={styles.contactInput}
            placeholder="Phone (optional)"
            value={input}
            onChangeText={setInput}
          />
          <View style={styles.modalButtons}>
            <Button title="Cancel" onPress={() => setShowAddModal(false)} />
            <Button title="Add Contact" onPress={addContact} />
          </View>
        </View>
      </Modal>

      {selectedContact && (
        <Modal visible={showAddModal} presentationStyle="modal">
          <View style={styles.contactModal}>
            <Text style={styles.contactModalTitle}>Edit Contact</Text>
            <TextInput style={styles.contactInput} value={selectedContact.name} onChangeText={(v) => {
              const updated = { ...selectedContact, name: v };
              setContacts(contacts.map(c => c.id === selectedContact.id ? updated : c));
            }} />
            <TextInput style={styles.contactInput} value={selectedContact.email} onChangeText={(v) => {
              const updated = { ...selectedContact, email: v };
              setContacts(contacts.map(c => c.id === selectedContact.id ? updated : c));
            }} />
            <TextInput style={styles.contactInput} value={selectedContact.phone} onChangeText={(v) => {
              const updated = { ...selectedContact, phone: v };
              setContacts(contacts.map(c => c.id === selectedContact.id ? updated : c));
            }} />
            <View style={styles.modalButtons}>
              <Button title="Cancel" onPress={() => setShowAddModal(false)} />
              <Button title="Save Changes" onPress={() => setShowAddModal(false)} />
            </View>
          </View>
        </Modal>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { padding: 16, gap: 16 },
  title: { fontSize: 28, fontWeight: 'bold', margin: 0 },
  subtitle: { fontSize: 14, color: '#666', marginTop: 4 },
  input: { borderWidth: 1, padding: 12, borderRadius: 8, marginBottom: 8 },
  searchInput: { borderWidth: 1, padding: 12, borderRadius: 8 },
  contactItem: { flexDirection: 'row', alignItems: 'center', padding: 12, borderBottomWidth: 1 },
  contactName: { fontWeight: 'bold', flex: 1 },
  contactInfo: { fontSize: 13, color: '#666' },
  deleteIcon: { marginLeft: 12, opacity: 0.5 },
  modal: { padding: 16, alignItems: 'center' },
  modalTitle: { fontSize: 18, fontWeight: 'bold', margin: 0 },
  contactInput: { borderWidth: 1, padding: 12, borderRadius: 8, marginBottom: 12 },
  modalButtons: { flexDirection: 'row', justifyContent: 'center', marginTop: 16 },
  contactModal: { padding: 16, gap: 16 },
  contactModalTitle: { fontSize: 18, fontWeight: 'bold' },
});
}
